import itertools
n=8
def is_costas(p):
    seen=set()
    for i in range(n):
        for j in range(i+1,n):
            v=(j-i,p[j]-p[i]) # or dr,dc; uniqueness equivalent with dc
            if v in seen: return False
            seen.add(v)
    return True
for p in itertools.permutations(range(n)):
    if is_costas(p):
        print(p)
        break
